    "description": "中新网银川10月12日电 (记者 李佩珊)2026年中国非物质文化遗产传承人研修培训计划——宁夏传统工艺类非物质文化遗产创造性转化创新性发展研修班，11日在宁夏大学开班。本次研修班由文化和旅游部支持，宁夏文旅厅与宁夏大学联合主办，宁夏大学民族与历史学院具体承办，吸引宁夏各地非遗代表性传承人参与学习。",
