    "content": "中新网上海10月12日电 2026中国女子高尔夫球公开赛(以下简称“中国女子公开赛”)11日在上海崇明岛PGA安瀛高尔夫俱乐部结束全部三轮比赛。刘宇婕在决赛轮交出69杆，以209杆、低于标准杆7杆的总成绩夺冠，拿下个人女子中巡第三冠，也成为中国女子公开赛创办二十年来的首位业余冠军。"
