    "content": "其实十年前就开始尽量避免挤地铁。 那时候三十出头，如今四十几。 那时候租房，每次跳操都涨工资。所以经常租公司附近，偶尔能够步行上下班。 如今自己的房子，远郊。 以前，有两年住回龙观附近，在西二旗上班。回龙观地铁很挤，龙泽站，就几乎挤不进去了，有一次我早餐没吃完，就地铁站买了一杯八宝粥，塑封，结果龙泽地铁站上车，给我挤破了。 如今在朝阳区。早上还好，但晚上得等到 7 点走。 哎，打完字，有点无病呻吟的感觉。 可能公司比较不卷吧，6 点就基本看不到人了。"
