    "content": "起因想要用 TS/JS 做一个桌面端小游戏，但选择框架的时候，但是发现并没有一个很好的选择。 Electron 过于庞大，内部集成了 node.js 和 chrome 谷歌浏览器 Tauri 虽然客户端小，但是使用系统自带的 WebView 渲染，会导致不同机器运行结果不一致 于是我准备使用 xbintsc,去编译这款桌面小游戏。 首先 xbintsc 优势： 构建体积小，最小可达 200kb ，编译可选 node 扩展(支持部分 node.js 的 API)最小可达 300kb ，编译可选 GUI 扩展(可视化界…"
