    "description": "2026年10月12日 本报记者 吴 君摄 \"> 青山环抱，松柏苍翠。 湖北省宣恩县李家河镇板栗园村，板栗园大捷纪念碑巍然矗立，碑身镌刻的“峥嵘岁月 血肉情谊”8个大字在阳光下熠熠生辉。纪念碑前，游客注视碑文，59岁的义务讲解员覃庆海声情并茂地讲述着那场1935年发生的激烈战斗。 1935年8月，红军借助截获的敌军密电掌握敌情，在板栗园设下伏击圈，全歼敌第85师师部、2个团又1个营，俘敌千余人。板栗园大捷是湘鄂川黔苏区反“围剿”的关键胜…",
    "content": "2026年10月12日 板栗园村的红军桥。 本报记者 吴 君摄 \"> 青山环抱，松柏苍翠。 湖北省宣恩县李家河镇板栗园村，板栗园大捷纪念碑巍然矗立，碑身镌刻的“峥嵘岁月&nbsp;&nbsp;血肉情谊”8个大字在阳光下熠熠生辉。纪念碑前，游客注视碑文，59岁的义务讲解员覃庆海声情并茂地讲述着那场1935年发生的激烈战斗。 1935年8月，红军借助截获的敌军密电掌握敌情，在板栗园设下伏击圈，全歼敌第85师师部、2个团又1个营，俘敌千余人。板栗园大捷是湘鄂川黔苏区反“围剿”的关键胜利，策应了中央红军长征。 为纪念此次胜…"
