    "description": "2026年10月12日 白山黑水间，秋日正好，层林斑斓。清晨薄雾中，一只东北虎缓步穿行于东北虎豹国家公园腹地林海间。 这一幕发生在数百公里外吉林珲春的深山中，却同步呈现在位于吉林长春的东北虎豹国家公园“天地空”一体化监测系统指挥中心的大屏上。系统比对老虎体侧与肩胛的花纹后，很快确认这只东北虎是园区记录在册的72只野生东北虎之一。 “老虎、豹子身上的斑纹就像人类的指纹，独一无二。”东北虎豹国家公园管理局综合业务处处长陈晓才指着大屏上的东北…",
    "content": "2026年10月12日 白山黑水间，秋日正好，层林斑斓。清晨薄雾中，一只东北虎缓步穿行于东北虎豹国家公园腹地林海间。 这一幕发生在数百公里外吉林珲春的深山中，却同步呈现在位于吉林长春的东北虎豹国家公园“天地空”一体化监测系统指挥中心的大屏上。系统比对老虎体侧与肩胛的花纹后，很快确认这只东北虎是园区记录在册的72只野生东北虎之一。 “老虎、豹子身上的斑纹就像人类的指纹，独一无二。”东北虎豹国家公园管理局综合业务处处长陈晓才指着大屏上的东北虎介绍，通过监测，系统汇集海量野外影像，然后对虎豹个体作初步识别，科研团队再结合…"
