    "content": "2026年10月12日 许钧在查阅资料。 本报记者 刘军国摄 \"> 人物小传 许钧，1954年生，浙江龙游人，翻译家，浙江大学文科资深教授，曾任国务院学位委员会外国语言文学学科评议组召集人、中国翻译协会常务副会长，现任《外语教学与研究》《中国翻译》等国内外10余种学术刊物的编委。译有《追忆似水年华》（卷四）、《不能承受的生命之轻》等法国文学与社科名著30余部，出版《翻译论》《翻译学概论》等著作10余部，曾获中国翻译协会“翻译事业特别贡献奖”等荣誉。 浙江衢州龙游县钱村，村口的有线喇叭是少年许钧认识外面世界的窗口。上…"
