    "description": "2026年10月12日 中华全国归国华侨联合会成立大会开幕典礼合影中，出席大会的代表们神情庄重、目光坚定，共同见证中国侨联事业扬帆启航。1956年10月12日，经党中央批准，中华全国归国华侨联合会在北京成立。 时光流转，初心不改。今年10月，中华全国归国华侨联合会迎来成立70周年。70年来，中国侨联始终听党话、跟党走，在中华民族伟大复兴的征程上留下侨界接续奋斗的铿锵足迹。 今年7月27日至28日，全国侨务工作会议在京召开。会上传达了习近…",
    "content": "2026年10月12日 中华全国归国华侨联合会成立大会开幕典礼合影中，出席大会的代表们神情庄重、目光坚定，共同见证中国侨联事业扬帆启航。1956年10月12日，经党中央批准，中华全国归国华侨联合会在北京成立。 时光流转，初心不改。今年10月，中华全国归国华侨联合会迎来成立70周年。70年来，中国侨联始终听党话、跟党走，在中华民族伟大复兴的征程上留下侨界接续奋斗的铿锵足迹。 今年7月27日至28日，全国侨务工作会议在京召开。会上传达了习近平总书记对侨务工作作出的重要指示。 “更好凝聚侨心侨力，引导广大海外侨胞和归侨侨…"
