    "description": "2026年10月12日 本报北京10月11日电 （记者吴丹）记者从教育部获悉：日前，教育部印发通知，启动第四届全国大学生职业规划大赛。大赛由教育部和重庆市人民政府共同主办，紧紧围绕“以赛促学、以赛促教、以赛促就”目标，努力打造强化生涯教育的大课堂、促进人才供需对接的大平台、服务毕业生就业的大市场。 大赛设置成长赛道、就业赛道，于2026年10月至2027年4月举办，采用校赛、省赛、全国总决赛三级赛制。校赛由各高校负责组织，省赛由各地负责…",
    "content": "2026年10月12日 本报北京10月11日电&nbsp;&nbsp;（记者吴丹）记者从教育部获悉：日前，教育部印发通知，启动第四届全国大学生职业规划大赛。大赛由教育部和重庆市人民政府共同主办，紧紧围绕“以赛促学、以赛促教、以赛促就”目标，努力打造强化生涯教育的大课堂、促进人才供需对接的大平台、服务毕业生就业的大市场。 大赛设置成长赛道、就业赛道，于2026年10月至2027年4月举办，采用校赛、省赛、全国总决赛三级赛制。校赛由各高校负责组织，省赛由各地负责组织。全国总决赛由重庆市教育委员会、重庆大学、重庆师范大学…"
