    "content": "2026年10月12日 本报北京10月11日电&nbsp;&nbsp;（记者林丽鹂）记者日前从市场监管总局获悉：目前，生产销售无CCC认证充电宝的违法违规行为已经得到明显遏制，生产经营主体的合规意识普遍提升。 2024年8月，充电宝纳入CCC认证管理后，监管部门发现市场上仍然存在生产、销售无CCC认证充电宝的情况，成为充电宝质量安全的严重隐患。为进一步消除隐患，市场监管总局印发《关于开展无CCC认证充电宝集中整治的通知》，部署为期三个月的集中整治。据了解，在市场监管总局认证监管司指导下，中国消费者报社在北京、上海、…"
