    "description": "2026年10月12日 今年1—9月，广东省全社会用电量7759.96亿千瓦时，同比增长7.67%。其中，7月份广东全社会用电量达1007.98亿千瓦时，成为全国首个单月用电量突破千亿千瓦时的省份；8月份，数据再度刷新，达1056亿千瓦时，持续保持增长。 新质生产力加速培育，第二产业向“新”而行，成为助推用电量增长的重要因素。数据显示，1—9月，广东第二产业用电量4373.87亿千瓦时，同比增长7.41%。其中，高技术及装备制造业用电量…",
    "content": "2026年10月12日 今年1—9月，广东省全社会用电量7759.96亿千瓦时，同比增长7.67%。其中，7月份广东全社会用电量达1007.98亿千瓦时，成为全国首个单月用电量突破千亿千瓦时的省份；8月份，数据再度刷新，达1056亿千瓦时，持续保持增长。 新质生产力加速培育，第二产业向“新”而行，成为助推用电量增长的重要因素。数据显示，1—9月，广东第二产业用电量4373.87亿千瓦时，同比增长7.41%。其中，高技术及装备制造业用电量同比增长8.61%，汽车制造业、专用设备制造业、计算机/通信和其他电子设备制造业…"
