    "content": "2026年10月12日 让执法温度与力度并存，凝聚社会各界共识，共同守护好“舌尖上的安全” 市场监管总局10月10日发布的《中华人民共和国食品安全法（修订草案征求意见稿）》对罚款制度进行了调整，直面近年来食品安全领域备受争议的“小过重罚”难题。 “榆林毒芹菜案”就是一个典型案例。2022年，陕西榆林某蔬菜粮油店因购进7斤、货值约20元的芹菜，被监管部门抽检发现禁用农药，处以6.6万元罚款。公众对此普遍觉得“不对劲儿”，获利与罚款相差悬殊，即使合法，从朴素的情理出发也感觉“太重了”。近年来，这类违法情节轻、货值小、社…"
