    "content": "2026年10月12日 大量古文化遗址、古墓葬、石窟寺、古石刻分布在乡间田野、山地荒坡，针对此类不可移动文物的犯罪行为隐蔽性强，不易被察觉。部分行为人对文物违法犯罪活动存在认知偏差，逐步走上文物犯罪道路。 在自家宅基地发现古墓葬，能挖出来卖吗？河道内捡到文物，该如何处置？……针对社会关注热点，最高人民法院、国家文物局10月10日发布6个依法惩治文物犯罪典型案例，旨在充分发挥司法裁判的规范引领作用，树立鲜明的价值导向，依法打击、有效防范文物犯罪。 在一起案例中，被告人师某兴为陕西省西安市长安区马王街道某村村民，该村位…"
