    "description": "2026年10月12日 本报甘肃白银10月11日电 （记者徐红梅、宋朝军）10日，甘肃省在白银市会宁县举行纪念红军长征三大主力会宁会师90周年座谈会，来自中央党史和文献研究院、甘肃省和白银市的相关同志，以及老红军亲属代表作了交流发言。 与会人士表示，要从长征的故事、革命的故事、英雄的故事中汲取强大精神力量，在伟大长征精神的感召下，坚定信心、乘势而上、勇毅前行，在现代化建设中不断创造新的伟大奇迹。座谈会前，与会同志前往红军会宁会师旧址，在…",
    "content": "2026年10月12日 本报甘肃白银10月11日电&nbsp;&nbsp;（记者徐红梅、宋朝军）10日，甘肃省在白银市会宁县举行纪念红军长征三大主力会宁会师90周年座谈会，来自中央党史和文献研究院、甘肃省和白银市的相关同志，以及老红军亲属代表作了交流发言。 与会人士表示，要从长征的故事、革命的故事、英雄的故事中汲取强大精神力量，在伟大长征精神的感召下，坚定信心、乘势而上、勇毅前行，在现代化建设中不断创造新的伟大奇迹。座谈会前，与会同志前往红军会宁会师旧址，在中国工农红军第一二四方面军会师纪念塔前向红军英烈敬献花篮，…"
