    "author": "",
    "description": "2026年10月12日 巴山蜀水，苍茫山林间，大熊猫安然栖息，川金丝猴、珙桐等同域珍稀动植物共生于此。刚刚过去的国庆假期，四川成都大熊猫繁育研究基地等景点游客众多，人们近距离观赏大熊猫们翻滚玩耍，走进大熊猫博物馆了解相关知识…… 四川的大熊猫种群数量与栖息地面积均居全国首位。2006年，四川大熊猫栖息地被列入《世界遗产名录》，四川由此拥有了全球最大、保存最完整的大熊猫栖息地世界自然遗产。2021年，大熊猫国家公园正式设立，四川片区涵盖了…",
    "content": "2026年10月12日 巴山蜀水，苍茫山林间，大熊猫安然栖息，川金丝猴、珙桐等同域珍稀动植物共生于此。刚刚过去的国庆假期，四川成都大熊猫繁育研究基地等景点游客众多，人们近距离观赏大熊猫们翻滚玩耍，走进大熊猫博物馆了解相关知识…… 四川的大熊猫种群数量与栖息地面积均居全国首位。2006年，四川大熊猫栖息地被列入《世界遗产名录》，四川由此拥有了全球最大、保存最完整的大熊猫栖息地世界自然遗产。2021年，大熊猫国家公园正式设立，四川片区涵盖了大熊猫栖息地世界自然遗产的大部分范围。 在世界自然遗产地与国家公园“双重身份”叠…"
