    "description": "2026年10月12日 本报北京10月11日电 （记者王浩）记者从中国长江三峡集团有限公司获悉：10日，三峡水运新通道葛洲坝航运扩能上下游围堰正式启动施工。这两道围堰将与岸坡等共同围护施工区域，为万吨级新船闸干地施工创造先决条件，这标志着葛洲坝航运扩能全面进入主体施工阶段。 三峡水运新通道包含三峡枢纽新通道和葛洲坝航运扩能两部分。其中，葛洲坝航运扩能位于葛洲坝枢纽左岸，将拆除既有三号船闸，并在原址新建两座万吨级船闸。未来，万吨级单船可顺…",
    "content": "2026年10月12日 本报北京10月11日电&nbsp;&nbsp;（记者王浩）记者从中国长江三峡集团有限公司获悉：10日，三峡水运新通道葛洲坝航运扩能上下游围堰正式启动施工。这两道围堰将与岸坡等共同围护施工区域，为万吨级新船闸干地施工创造先决条件，这标志着葛洲坝航运扩能全面进入主体施工阶段。 三峡水运新通道包含三峡枢纽新通道和葛洲坝航运扩能两部分。其中，葛洲坝航运扩能位于葛洲坝枢纽左岸，将拆除既有三号船闸，并在原址新建两座万吨级船闸。未来，万吨级单船可顺畅通过葛洲坝枢纽。 2026-10-12 00:00:00…"
