    "content": "2026年10月12日 本报兰州10月11日电&nbsp;&nbsp;（记者曾亦辰）甘肃省林草局等部门日前印发《甘肃省林业草原保护利用“十五五”规划》，明确到2030年，“三北”工程攻坚战取得决定性胜利，完成自然保护地整合优化，森林、草原、湿地、荒漠生态系统质量和功能不断增强，林草产业规模稳步壮大，总产值再上新台阶。 该规划以筑牢国家西部生态安全屏障为目标，聚焦“三北”工程、黄河流域生态保护和高质量发展等国家重大战略，布局“三北”工程六期、重要生态系统保护和修复、自然保护地体系建设、野生动植物保护、森林质量精准提升…"
