    "description": "2026年10月12日 浙江省绍兴市上虞区，五山一水四分田，正成为青年入乡发展的热土。 近3年，上虞区建成乡村人才创业园3个、青年入乡实践站点16家，涉及种植养殖、农产电商、农创研学等特色产业，累计吸引青年入乡创业就业1.8万人，带动1.1万余户农户增收超3.5亿元。 今年8月，上虞区入选浙江省首批青年入乡发展改革试点，围绕工作机制、政策供给、要素支持、培育提能等七大领域，致力为青年入乡发展探路先行。 乡村全面振兴，人才是关键。当年轻人…",
    "content": "2026年10月12日 浙江省绍兴市上虞区，五山一水四分田，正成为青年入乡发展的热土。 近3年，上虞区建成乡村人才创业园3个、青年入乡实践站点16家，涉及种植养殖、农产电商、农创研学等特色产业，累计吸引青年入乡创业就业1.8万人，带动1.1万余户农户增收超3.5亿元。 今年8月，上虞区入选浙江省首批青年入乡发展改革试点，围绕工作机制、政策供给、要素支持、培育提能等七大领域，致力为青年入乡发展探路先行。 乡村全面振兴，人才是关键。当年轻人带着闯劲与热望入乡发展，乡村全面振兴画卷又添青春与乡土“双向奔赴”的动人场景。 …"
