    "description": "2026年10月12日 林双伟摄 \"> 池 远摄 \"> 滕一郎摄 \"> 黄淑贞摄 \"> 受访者供图 \">林双伟摄 \" style=\"max-width: 100%; white-space: normal;\"> 东海之滨，闽江入海，福建福州派江吻海、百河润邑、群翠绕城。 这座国家历史文化名城，2200多年的建城史沿着中轴线自北向南生长。从新店古城遗址、西汉冶城遗址，到三坊七巷与朱紫坊，再到上下杭、烟台山等，沉淀下厚重的千年文脉，镌刻着向…",
    "content": "2026年10月12日 永泰县白云乡竹头寨。 林双伟摄 \"> 外国游客游览三坊七巷历史文化街区。 池 远摄 \"> 扬·马尔托雷尔在制作咖啡。 滕一郎摄 \"> 宋怡明（左一）与学生们在永泰县探讨永泰文书。 黄淑贞摄 \"> 令和在工作室运用中国传统文化元素创作当代艺术作品。 受访者供图 \"> 福州中轴线上的三坊七巷历史文化街区俯瞰。 林双伟摄 \" style=\"max-width: 100%; white-space: normal;\"> 东海之滨，闽江入海，福建福州派江吻海、百河润邑、群翠绕城。 这座国家历史文化名城…"
